			{Text: " bookmarks  ", Kind: statusbar.KindNormal},
			{Text: "Shift+L", Kind: statusbar.KindAccent},
			{Text: " load  ", Kind: statusbar.KindNormal},
			{Text: "Shift+U", Kind: statusbar.KindAccent},
