package tui

import (
	"strings"
	"unicode"

	"github.com/charmbracelet/x/ansi"
	"github.com/ishansain/gotui"
	"github.com/ishansain/gotui/textinput"

	"nice-llama-server/internal/config"
)

const (
	maxVisibleArgCompletions = 4
	maxUndoDepth             = 50
)

type textSnapshot struct {
	lines [][]rune
	row   int
	col   int
}

type bookmarkEditor struct {
	originalID  string
	isNew       bool
	modelPath   string
	groupKey    string
	initialName string
	initialArgs string
	name        textinput.Model
	args        textBuffer
	completion  argCompletionState
}

func newBookmarkEditor(b config.Bookmark, isNew bool, theme gotui.Theme) *bookmarkEditor {
	e := &bookmarkEditor{
		originalID:  b.ID,
		isNew:       isNew,
		modelPath:   b.ModelPath,
		groupKey:    b.GroupKey,
		initialName: strings.TrimSpace(b.Name),
		initialArgs: strings.TrimSpace(b.ArgsText),
		name:        textinput.New(theme),
		args:        newTextBuffer(b.ArgsText, true),
	}
	e.name.SetValue(b.Name)
	e.name.Prompt = ""
	return e
}

func (e *bookmarkEditor) Bookmark() config.Bookmark {
	return config.Bookmark{
		ID:        e.originalID,
		Name:      strings.TrimSpace(e.name.Value()),
		ModelPath: e.modelPath,
		GroupKey:  e.groupKey,
		ArgsText:  strings.TrimSpace(e.args.Value()),
	}
}

func (e *bookmarkEditor) Dirty() bool {
	return strings.TrimSpace(e.name.Value()) != e.initialName ||
		strings.TrimSpace(e.args.Value()) != e.initialArgs
}

type argCompletionState struct {
	active     bool
	passive    bool
	row        int
	start      int
	end        int
	prefix     string
	index      int
	candidates []argCompletionCandidate
}

type argCompletionCandidate struct {
	Text        string
	optionIndex int
}

type tokenContext struct {
	row    int
	start  int
	end    int
	prefix string
	token  string
}

type lineToken struct {
	start int
	end   int
	text  string
}

type textBuffer struct {
