	m := newModel(context.Background(), nil)
	for i := 0; i < 5; i++ {
		m.logs = append(m.logs, config.LogEntry{
			Seq:    int64(i + 1),
			Stream: "stdout",
			Line:   "line",
		})
	}
	// Render once to set viewport size and content
	m.renderLogView(40, 6)
	m.logView.GotoBottom()
	if !m.logView.AtBottom() {
		t.Fatalf("expected viewport to be at bottom after GotoBottom")
	}

	m.followTailEnabled = true
	next, _ := m.Update(logsMsg{entries: []config.LogEntry{{
		Seq:    6,
		Stream: "stdout",
		Line:   "new line",
	}}})
	got := next.(*model)
	if !got.logView.AtBottom() {
		t.Fatalf("expected auto-follow when already at bottom and tail mode enabled")
	}

	got.followTailEnabled = false
	got.logView.ScrollTo(0)
	yoffBefore := got.logView.YOffset()
	next, _ = got.Update(logsMsg{entries: []config.LogEntry{{
		Seq:    7,
		Stream: "stdout",
		Line:   "another line",
	}}})
	got = next.(*model)
	if got.logView.YOffset() != yoffBefore {
		t.Fatalf("expected viewport position to stay when scrolled up and tail mode disabled, got yoff=%d (before=%d)", got.logView.YOffset(), yoffBefore)
	}

	got.followTailEnabled = true
	got.logView.ScrollTo(0)
	yoffBefore = got.logView.YOffset()
	next, _ = got.Update(logsMsg{entries: []config.LogEntry{{
		Seq:    8,
		Stream: "stdout",
		Line:   "followed line",
	}}})
	got = next.(*model)
	if got.logView.YOffset() != yoffBefore {
