func TestHeaderRespectsFiveLineCap(t *testing.T) {
	t.Parallel()

	m := newModel(context.Background(), nil)
	m.width = 100
	m.snapshot = config.Snapshot{
		Bookmarks: []config.Bookmark{{ID: "1", Name: "Gemma"}},
		Models: []config.DiscoveredModel{{
			Path:        "/models/gemma.gguf",
			DisplayName: "gemma-3-4b-it-Q4_K_M",
			GroupKey:    "gemma-3-4b-it-Q4_K_M",
		}},
		Config: config.Config{ModelRoots: []string{"/models"}},
		Runtime: config.RuntimeState{
			Status: config.StatusReady,
			Host:   "127.0.0.1",
			Port:   8080,
		},
	}

	header := ansi.Strip(m.renderHeader(100))
	if lines := strings.Count(header, "\n") + 1; lines != headerPanelHeight {
		t.Fatalf("unexpected header height: got %d want %d\n%s", lines, headerPanelHeight, header)
	}
	if !strings.Contains(header, "Nice Llama Server") {
		t.Fatalf("expected header title to remain visible: %q", header)
	}
	// With frame.Panel the title is in the top border, not the body.
	// Verify the body content still shows runtime status and stats.
	if !strings.Contains(header, "READY") {
		t.Fatalf("expected runtime status in header: %q", header)
	}
	if !strings.Contains(header, "8080") {
		t.Fatalf("expected port in header: %q", header)
	}
}

func TestFooterChangesByContext(t *testing.T) {
	t.Parallel()

	m := newModel(context.Background(), nil)
	// Bookmarks view footer should mention logs toggle
	if line := ansi.Strip(m.renderFooter(100)); !strings.Contains(line, "logs") {
		t.Fatalf("bookmark footer should mention logs toggle: %q", line)
	}

	// Switch to logs view
	m.tabs.SelectID("logs")
	if line := ansi.Strip(m.renderFooter(100)); !strings.Contains(line, "bookmarks") {
		t.Fatalf("log footer should mention bookmarks toggle: %q", line)
	}

	// Editor mode should show save key
	m.tabs.SelectID("bookmarks")
	m.editor = newBookmarkEditor(config.Bookmark{Name: "test"}, true, m.theme)
	m.focus = focusDetailName
	if line := ansi.Strip(m.renderFooter(100)); !strings.Contains(line, "save") {
		t.Fatalf("editor footer should mention save: %q", line)
	}

	// Confirm delete mode
	m.editor = nil
	m.showDialog = true
	if line := ansi.Strip(m.renderFooter(100)); !strings.Contains(line, "delete") {
		t.Fatalf("confirm delete footer should mention delete: %q", line)
	}
}

