func TestLogViewHorizontalSliceShowsScrolledPortion(t *testing.T) {
	t.Parallel()

	m := newModel(context.Background(), nil)
	m.tabs.SelectID("logs")
	m.logScrollX = 5
	m.logs = []config.LogEntry{{
		Seq:    1,
		TS:     time.Unix(0, 0),
		Stream: "stdout",
		Line:   "abcdefghijklmno",
	}}

	// renderLogView formats content and sets it on the viewport
	view := m.renderLogView(40, 4)
	// Strip ANSI and check for the horizontally scrolled content
	stripped := ansi.Strip(view)
	// With scroll offset 5, we expect "fghijklmno" (starting from index 5)
	if !strings.Contains(stripped, "fgh") {
		t.Fatalf("expected scrolled log content 'fgh' to be present, got %q", stripped)
	}
	if strings.Contains(stripped, "abcdefghijklmno") {
		t.Fatalf("expected long line to be horizontally sliced, got %q", stripped)
	}
	// Ensure we don't see the beginning
	if strings.Contains(stripped, "abcde") {
		t.Fatalf("expected horizontal scroll to hide beginning of line, got %q", stripped)
	}
}

func TestLogViewVerticalWindowUsesScrollOffset(t *testing.T) {
