	got := formatLogTimestamp(ts, loc)
	want := "10:02:03"
	if got != want {
		t.Fatalf("unexpected timestamp format with fixed location: got %q want %q", got, want)
	}
}

func TestRenderLogTimestampsUseSystemLocal(t *testing.T) {
