	testLocal := time.FixedZone("UTC+02", 2*60*60)
	time.Local = testLocal
	defer func() {
		time.Local = originalLocal
	}()

	ts := time.Date(2024, time.January, 2, 1, 2, 3, 0, time.UTC)
	expected := formatLogTimestamp(ts, testLocal)

	m := newModel(context.Background(), nil)
	m.logs = []config.LogEntry{{
		Seq:    1,
		TS:     ts,
		Stream: "stdout",
		Line:   "server started",
	}}

	view := m.renderLogView(40, 4)
	if got := ansi.Strip(view); !strings.Contains(got, expected) {
		t.Fatalf("expected renderLogView output to include local timestamp %q, got %q", expected, got)
	}
}

