package tui

import (
	"context"
	"strings"
	"testing"
	"time"

	tea "charm.land/bubbletea/v2"
	lipgloss "charm.land/lipgloss/v2"
	"github.com/charmbracelet/x/ansi"

	"nice-llama-server/internal/config"
)

func TestHeaderRespectsFiveLineCap(t *testing.T) {
	t.Parallel()

	m := newModel(context.Background(), nil)
	m.width = 100
	m.snapshot = config.Snapshot{
		Bookmarks: []config.Bookmark{{ID: "1", Name: "Gemma"}},
		Models: []config.DiscoveredModel{{
			Path:        "/models/gemma.gguf",
			DisplayName: "gemma-3-4b-it-Q4_K_M",
			GroupKey:    "gemma-3-4b-it-Q4_K_M",
		}},
		Config: config.Config{ModelRoots: []string{"/models"}},
		Runtime: config.RuntimeState{
			Status: config.StatusReady,
			Host:   "127.0.0.1",
			Port:   8080,
		},
	}

	header := ansi.Strip(m.renderHeader(100))
	if lines := strings.Count(header, "\n") + 1; lines != headerPanelHeight {
		t.Fatalf("unexpected header height: got %d want %d\n%s", lines, headerPanelHeight, header)
	}
	if !strings.Contains(header, "Nice Llama Server") {
		t.Fatalf("expected header title to remain visible: %q", header)
	}
	// With frame.Panel the title is in the top border, not the body.
	// Verify the body content still shows runtime status and stats.
	if !strings.Contains(header, "READY") {
		t.Fatalf("expected runtime status in header: %q", header)
	}
	if !strings.Contains(header, "8080") {
		t.Fatalf("expected port in header: %q", header)
	}
}

func TestFooterChangesByContext(t *testing.T) {
	t.Parallel()

	m := newModel(context.Background(), nil)
	// Bookmarks view footer should mention logs toggle
	if line := ansi.Strip(m.renderFooter(100)); !strings.Contains(line, "logs") {
		t.Fatalf("bookmark footer should mention logs toggle: %q", line)
	}

	// Switch to logs view
	m.tabs.SelectID("logs")
	if line := ansi.Strip(m.renderFooter(100)); !strings.Contains(line, "bookmarks") {
		t.Fatalf("log footer should mention bookmarks toggle: %q", line)
	}

	// Editor mode should show save key
	m.tabs.SelectID("bookmarks")
	m.editor = newBookmarkEditor(config.Bookmark{Name: "test"}, true, m.theme)
	m.focus = focusDetailName
	if line := ansi.Strip(m.renderFooter(100)); !strings.Contains(line, "save") {
		t.Fatalf("editor footer should mention save: %q", line)
	}

	// Confirm delete mode
	m.editor = nil
	m.showDialog = true
	if line := ansi.Strip(m.renderFooter(100)); !strings.Contains(line, "delete") {
		t.Fatalf("confirm delete footer should mention delete: %q", line)
	}
}

func TestFocusedBookmarkNameRendersCursor(t *testing.T) {
	t.Parallel()

	m := newModel(context.Background(), nil)
	m.focus = focusDetailName
	m.editor = newBookmarkEditor(config.Bookmark{Name: "Gemma"}, false, m.theme)
	m.editor.name.Focus()

	rendered := ansi.Strip(strings.Join(m.renderDetailLines(50, 10), "\n"))
	// textinput renders cursor as a reversed block; when ANSI-stripped it's a space.
	// Verify the name field content is rendered (cursor presence is visual only).
	if !strings.Contains(rendered, "Gemma") {
		t.Fatalf("expected bookmark name in focused field: %q", rendered)
	}
}

func TestArgsCompletionRendersInlineGhostOptions(t *testing.T) {
	t.Parallel()

	m := newModel(context.Background(), nil)
	m.focus = focusDetailArgs
	m.editor = newBookmarkEditor(config.Bookmark{ArgsText: "--ctx"}, false, m.theme)
	m.editor.args.MoveEnd()

	next, _ := m.Update(tea.KeyPressMsg(tea.Key{Code: tea.KeyTab}))
	got := next.(*model)

	rendered := ansi.Strip(strings.Join(got.renderDetailLines(80, 10), "\n"))
	if !strings.Contains(rendered, "--ctx-size") {
		t.Fatalf("expected selected completion in args editor: %q", rendered)
	}
	if !strings.Contains(rendered, "--ctx-checkpoints") && !strings.Contains(rendered, "--ctx-size-draft") {
		t.Fatalf("expected inline alternate completions in args editor: %q", rendered)
	}
}

func TestMMProjCompletionRendersInlineGhostOptions(t *testing.T) {
	t.Parallel()

	m := newModel(context.Background(), nil)
	m.focus = focusDetailArgs
	m.editor = newBookmarkEditor(config.Bookmark{
		ModelPath: "/models/vision.gguf",
		ArgsText:  "-mm ",
	}, false, m.theme)
	m.snapshot.Models = []config.DiscoveredModel{{
		Path:        "/models/vision.gguf",
		DisplayName: "vision",
		MMProjPaths: []string{"/models/mmproj-a.gguf", "/models/mmproj-b.gguf"},
	}}
	m.editor.args.MoveEnd()

	next, _ := m.Update(tea.KeyPressMsg(tea.Key{Code: tea.KeyTab}))
	got := next.(*model)

	rendered := ansi.Strip(strings.Join(got.renderDetailLines(80, 10), "\n"))
	if !strings.Contains(rendered, "/models/mmproj-a.gguf") {
		t.Fatalf("expected selected mmproj completion in args editor: %q", rendered)
	}
	if !strings.Contains(rendered, "/models/mmproj-b.gguf") {
		t.Fatalf("expected alternate mmproj ghost completion in args editor: %q", rendered)
	}
}

func TestPassiveSingleHyphenCompletionRendersInlineGhostOptions(t *testing.T) {
	t.Parallel()

	m := newModel(context.Background(), nil)
	m.focus = focusDetailArgs
	m.editor = newBookmarkEditor(config.Bookmark{}, false, m.theme)

	next, _ := m.Update(tea.KeyPressMsg{Text: "-"})
	got := next.(*model)

	rendered := ansi.Strip(strings.Join(got.renderDetailLines(80, 10), "\n"))
	if !strings.Contains(rendered, "-h") {
		t.Fatalf("expected passive single-hyphen options in args editor: %q", rendered)
	}
}

func TestToggleViewDoesNotSetShowingStatusMessage(t *testing.T) {
	t.Parallel()

	m := newModel(context.Background(), nil)
	m.Update(tea.KeyPressMsg{Text: "/"})
	if got := m.messageLine(); got != "" {
		t.Fatalf("toggle should not set a showing message, got %q", got)
	}
}

func TestRenderLogViewUsesBottomContainerWidth(t *testing.T) {
	t.Parallel()

	m := newModel(context.Background(), nil)
	m.tabs.SelectID("logs")
	m.width = 90
	m.height = 24
	m.logs = []config.LogEntry{{
		Seq:    1,
		TS:     time.Unix(0, 0),
		Stream: "stdout",
		Line:   "server started",
	}}

	rendered := ansi.Strip(m.renderBottom(90, 12))
	if !strings.Contains(rendered, "Runtime Logs") {
		t.Fatalf("expected log title in log view: %q", rendered)
	}
	if strings.Contains(rendered, "Bookmark Detail") {
		t.Fatalf("log view should not render bookmark detail panel")
	}
}

func TestLogViewHorizontalSliceShowsScrolledPortion(t *testing.T) {
	t.Parallel()

	m := newModel(context.Background(), nil)
	m.tabs.SelectID("logs")
	m.logScrollX = 5
	m.logs = []config.LogEntry{{
		Seq:    1,
		TS:     time.Unix(0, 0),
		Stream: "stdout",
		Line:   "abcdefghijklmno",
	}}

	// renderLogView formats content and sets it on the viewport
	view := m.renderLogView(40, 4)
	// Strip ANSI and check for the horizontally scrolled content
	stripped := ansi.Strip(view)
	// With scroll offset 5, we expect "fghijklmno" (starting from index 5)
	if !strings.Contains(stripped, "fgh") {
		t.Fatalf("expected scrolled log content 'fgh' to be present, got %q", stripped)
	}
	if strings.Contains(stripped, "abcdefghijklmno") {
		t.Fatalf("expected long line to be horizontally sliced, got %q", stripped)
	}
	// Ensure we don't see the beginning
	if strings.Contains(stripped, "abcde") {
		t.Fatalf("expected horizontal scroll to hide beginning of line, got %q", stripped)
	}
}

func TestLogViewVerticalWindowUsesScrollOffset(t *testing.T) {
	t.Parallel()

	m := newModel(context.Background(), nil)
	m.tabs.SelectID("logs")
	for i := 0; i < 4; i++ {
		m.logs = append(m.logs, config.LogEntry{
			Seq:    int64(i + 1),
			TS:     time.Unix(int64(i), 0),
			Stream: "stdout",
			Line:   string(rune('A' + i)),
		})
	}

	// Render to set viewport content, then scroll down by 1
	m.renderLogView(40, 3)
	m.logView.ScrollBy(1)

	view := m.renderLogView(40, 3)
	stripped := ansi.Strip(view)
	if strings.Contains(stripped, "A") {
		t.Fatalf("expected first log line to be scrolled out, got %q", stripped)
	}
	if !strings.Contains(stripped, "B") {
		t.Fatalf("expected scrolled window to start later, got %q", stripped)
	}
}

func TestFormatLogTimestampNilLocation(t *testing.T) {
	t.Parallel()

	ts := time.Date(2024, time.January, 2, 3, 4, 5, 0, time.FixedZone("UTC-07", -7*60*60))
	got := formatLogTimestamp(ts, nil)
	want := ts.Format("15:04:05")
	if got != want {
		t.Fatalf("unexpected timestamp format with nil location: got %q want %q", got, want)
	}
}

func TestFormatLogTimestampFixedLocation(t *testing.T) {
	t.Parallel()

	ts := time.Date(2024, time.January, 2, 1, 2, 3, 0, time.UTC)
	loc := time.FixedZone("UTC+09", 9*60*60)

	got := formatLogTimestamp(ts, loc)
	want := "10:02:03"
	if got != want {
		t.Fatalf("unexpected timestamp format with fixed location: got %q want %q", got, want)
	}
}

func TestRenderLogTimestampsUseSystemLocal(t *testing.T) {
	originalLocal := time.Local
	testLocal := time.FixedZone("UTC+02", 2*60*60)
	time.Local = testLocal
	defer func() {
		time.Local = originalLocal
	}()

	ts := time.Date(2024, time.January, 2, 1, 2, 3, 0, time.UTC)
	expected := formatLogTimestamp(ts, testLocal)

	m := newModel(context.Background(), nil)
	m.logs = []config.LogEntry{{
		Seq:    1,
		TS:     ts,
		Stream: "stdout",
		Line:   "server started",
	}}

	view := m.renderLogView(40, 4)
	if got := ansi.Strip(view); !strings.Contains(got, expected) {
		t.Fatalf("expected renderLogView output to include local timestamp %q, got %q", expected, got)
	}
}

func TestBookmarkEditorViewFillsExactBottomRegion(t *testing.T) {
